import sys

data = sys.stdin.read().split()
n, m = int(data[0]), int(data[1])
by = {}
for i in range(m):
    a, d, p = int(data[2 + 3 * i]), int(data[3 + 3 * i]), int(data[4 + 3 * i])
    by.setdefault(p, []).append((d, a))
total = 0
for p, lst in by.items():
    lst.sort()
    dp = [1] * len(lst)
    for i in range(len(lst)):
        for j in range(i):
            if lst[j][0] <= lst[i][1]:
                dp[i] = max(dp[i], dp[j] + 1)
    total += max(dp)
print(total)

